[{"order":1,"type":"heading","text":"Building Custom Native Modules and Native Components in React Native"},{"order":2,"type":"paragraph","text":"While React Native offers a rich set of built-in components and APIs, advanced applications often require direct access to platform-specific native APIs and custom UI views written in Swift (iOS) and Kotlin (Android). This tutorial covers the end-to-end process of building both a Native Module (for business logic/APIs) and a Native Component (for UI views)."},{"order":3,"type":"subheading","text":"Part 1: Building a Native Module (iOS - Swift)"},{"order":4,"type":"paragraph","text":"Native modules are bridge classes that expose native device capabilities to JavaScript. Let's create a custom module named 'RNDeviceInfo' that returns system information."},{"order":5,"type":"paragraph","text":"First, create a new file named RNDeviceInfo.swift in your iOS Xcode project folder and implement the native bridge:"},{"order":6,"type":"code","text":"import Foundation
import React

@objc(RNDeviceInfo)
class RNDeviceInfo: NSObject {

  @objc
  static func requiresMainQueueSetup() -> Bool {
    return false
  }

  @objc
  func getDeviceVersion(_ resolve: RCTPromiseResolveBlock, rejecter reject: RCTPromiseRejectBlock) {
    let systemVersion = UIDevice.current.systemVersion
    resolve(systemVersion)
  }
}"},{"order":7,"type":"paragraph","text":"Next, expose the module to React Native by creating a corresponding Objective-C bridge file named RNDeviceInfo.m:"},{"order":8,"type":"code","text":"#import <React/RCTBridgeModule.h>

@interface RCT_EXTERN_MODULE(RNDeviceInfo, NSObject)

RCT_EXTERN_METHOD(getDeviceVersion:(RCTPromiseResolveBlock)resolve
                  rejecter:(RCTPromiseRejectBlock)reject)

@end"},{"order":9,"type":"subheading","text":"Part 2: Building a Native Module (Android - Kotlin)"},{"order":10,"type":"paragraph","text":"For Android, we need to implement a ReactContextBaseJavaModule in Kotlin."},{"order":11,"type":"paragraph","text":"Create a file named RNDeviceInfoModule.kt inside your android/app/src/main/java/com/yourpackage/ folder:"},{"order":12,"type":"code","text":"package com.yourpackage

import android.os.Build
import com.facebook.react.bridge.ReactApplicationContext
import com.facebook.react.bridge.ReactContextBaseJavaModule
import com.facebook.react.bridge.ReactMethod
import com.facebook.react.bridge.Promise

class RNDeviceInfoModule(reactContext: ReactApplicationContext) : ReactContextBaseJavaModule(reactContext) {

    override fun getName(): String {
        return "RNDeviceInfo"
    }

    @ReactMethod
    fun getDeviceVersion(promise: Promise) {
        try {
            val androidVersion = Build.VERSION.RELEASE
            promise.resolve(androidVersion)
        } catch (e: Exception) {
            promise.reject("ERROR", e)
        }
    }
}"},{"order":13,"type":"paragraph","text":"To register this module, create a package provider class named RNDeviceInfoPackage.kt:"},{"order":14,"type":"code","text":"package com.yourpackage

import android.view.View
import com.facebook.react.ReactPackage
import com.facebook.react.bridge.NativeModule
import com.facebook.react.bridge.ReactApplicationContext
import com.facebook.react.uimanager.ViewManager

class RNDeviceInfoPackage : ReactPackage {
    override fun createNativeModules(reactContext: ReactApplicationContext): List<NativeModule> {
        return listOf(RNDeviceInfoModule(reactContext))
    }

    override fun createViewManagers(reactContext: ReactApplicationContext): List<ViewManager<*, *>> {
        return emptyList()
    }
}"},{"order":15,"type":"subheading","text":"Part 3: Building a Native UI Component (iOS - Swift)"},{"order":16,"type":"paragraph","text":"Native components allow rendering platform-specific UI views inside React Native. Let us build a custom wrapper around a native map or a styled switch view."},{"order":17,"type":"paragraph","text":"Create a custom UIView subclass named CustomButtonView.swift:"},{"order":18,"type":"code","text":"import UIKit

class CustomButtonView: UIView {

  @objc var onClicked: RCTDirectEventBlock?

  let button = UIButton(type: .system)

  override init(frame: CGRect) {
    super.init(frame: frame)
    setupButton()
  }

  required init?(coder: coder) {
    fatalError("init(coder:) has not been implemented")
  }

  private func setupButton() {
    button.setTitle("Native Button", for: .normal)
    button.backgroundColor = .systemBlue
    button.setTitleColor(.white, for: .normal)
    button.layer.cornerRadius = 8
    button.addTarget(self, action: #selector(buttonTapped), for: .touchUpInside)

    addSubview(button)
    button.translatesAutoresizingMaskIntoConstraints = false
    NSLayoutConstraint.activate([
      button.centerXAnchor.constraint(equalTo: centerXAnchor),
      button.centerYAnchor.constraint(equalTo: centerYAnchor),
      button.widthAnchor.constraint(equalToConstant: 200),
      button.heightAnchor.constraint(equalToConstant: 50)
    ])
  }

  @objc private func buttonTapped() {
    if let onClicked = onClicked {
      onClicked([:])
    }
  }
}"},{"order":19,"type":"paragraph","text":"Now, expose the view using an RCTViewManager bridge class named CustomButtonManager.m:"},{"order":20,"type":"code","text":"#import <React/RCTViewManager.h>

@interface RCT_EXTERN_MODULE(CustomButtonManager, RCTViewManager)
RCT_EXPORT_VIEW_PROPERTY(onClicked, RCTDirectEventBlock)
@end"},{"order":21,"type":"subheading","text":"Part 4: Building a Native UI Component (Android - Kotlin)"},{"order":22,"type":"paragraph","text":"For Android, extend SimpleViewManager to manage custom UI components."},{"order":23,"type":"code","text":"package com.yourpackage

import android.widget.Button
import com.facebook.react.bridge.Arguments
import com.facebook.react.bridge.WritableMap
import com.facebook.react.uimanager.SimpleViewManager
import com.facebook.react.uimanager.ThemedReactContext
import com.facebook.react.uimanager.annotations.ReactProp
import com.facebook.react.uimanager.events.RCTEventEmitter

class CustomButtonManager : SimpleViewManager<Button>() {

    override fun getName(): String {
        return "CustomButton"
    }

    override fun createViewInstance(reactContext: ThemedReactContext): Button {
        val button = Button(reactContext)
        button.text = "Android Native Button"
        button.setOnClickListener {
            val event: WritableMap = Arguments.createMap()
            reactContext.getJSModule(RCTEventEmitter::class.java)
                .receiveEvent(button.id, "onClicked", event)
        }
        return button
    }
}"},{"order":24,"type":"subheading","text":"Part 5: Consuming in JavaScript/TypeScript"},{"order":25,"type":"paragraph","text":"Finally, consume your native module and native component inside your React Native application codebase."},{"order":26,"type":"code","text":"import React, { useEffect, useState } from 'react';
import { StyleSheet, Text, View, NativeModules, requireNativeComponent } from 'react-native';

const { RNDeviceInfo } = NativeModules;
const NativeCustomButton = requireNativeComponent('CustomButton');

export default function App() {
  const [version, setVersion] = useState('');

  useEffect(() => {
    RNDeviceInfo.getDeviceVersion()
      .then((ver: string) => setVersion(ver))
      .catch((err: any) => console.error(err));
  }, []);

  return (
    <View style={styles.container}>
      <Text style={styles.text}>System Version: {version}</Text>
      <NativeCustomButton 
        style={styles.button}
        onClicked={() => console.log('Native button clicked!')}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, justifyContent: 'center', alignItems: 'center' },
  text: { fontSize: 18, marginBottom: 20 },
  button: { width: 200, height: 50 }
});"},{"order":27,"bullet_point":"Always verify that your native modules register their names accurately across Java/Kotlin and Objective-C/Swift bounds."},{"order":28,"bullet_point":"Use Promises for asynchronous native module execution to prevent blocking the JavaScript thread."}]
